<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Illuminate\Validation\Rule; use Pterodactyl\Facades\Activity; use Illuminate\Http\Client\ConnectionException; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Catalogue\AddonCatalogue; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonToggleRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonInstallRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonDeleteRequest; abstract class AddonController extends ClientApiController { public function __construct(protected readonly AddonCatalogue $catalogue) { parent::__construct(); } protected const DISABLED_SUFFIX = '.disabled'; protected const MANIFEST_SUFFIX = 'addons.json'; protected const MANIFEST_LIMIT = 262144; protected const AGENT = 'Pterodactyl-Stark/1.0 (addon manager)'; protected const VERSION_TTL = 86400; abstract protected function directory(): string; abstract protected function sources(): array; abstract protected function projectTypes(): array; abstract protected function loaders(): array; abstract protected function usageKind(): string; protected function curseforgeClass(): int { return 0; } public function index(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse($this->installed($server) + [ 'sources' => $this->sources(), 'loaders' => $this->loaders(), ]); } public function gameVersions(AddonRequest $request, Server $server): JsonResponse { try { $versions = Cache::remember('addons:game-versions', self::VERSION_TTL, function () { $response = Http::withHeaders(['User-Agent' => self::AGENT]) ->timeout(15) ->get('https://api.modrinth.com/v2/tag/game_version'); if ($response->failed()) { return []; } return collect($response->json() ?? []) ->filter(fn (array $tag) => ($tag['version_type'] ?? '') === 'release') ->pluck('version') ->values() ->all(); }); } catch (ConnectionException) { $versions = []; } return new JsonResponse(['versions' => $versions]); } public function search(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->sources())], 'query' => ['present', 'nullable', 'string', 'max:120'], 'version' => ['nullable', 'string', 'max:20'], 'loader' => ['nullable', 'string', Rule::in($this->loaders())], 'page' => ['nullable', 'integer', 'min:1', 'max:' . AddonCatalogue::MAX_PAGE], ]); try { $payload = $this->catalogue->search( (string) $data['source'], trim((string) ($data['query'] ?? '')), $this->projectTypes(), $this->loaders(), (string) ($data['loader'] ?? ''), (string) ($data['version'] ?? ''), (int) ($data['page'] ?? 1), $this->curseforgeClass(), ); } catch (ConnectionException) { return $this->unreachable(); } return new JsonResponse($payload + ['maxPage' => AddonCatalogue::MAX_PAGE]); } public function versions(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->sources())], 'id' => ['required', 'string', 'max:120'], ]); try { $versions = $this->catalogue->versions((string) $data['source'], (string) $data['id']); } catch (ConnectionException) { return $this->unreachable(); } return new JsonResponse(['versions' => array_map($this->marked(...), $versions)]); } protected function marked(array $version): array { $fits = $this->fits($version); $version['installable'] = ($version['installable'] ?? true) && $fits; if (!$fits) { $version['reason'] = 'No loader this folder takes'; } return $version; } protected function fits(array $version): bool { $its = array_map( fn (mixed $loader) => mb_strtolower((string) $loader), (array) ($version['loaders'] ?? []), ); return $its === [] || array_intersect($this->loaders(), $its) !== []; } public function install(AddonInstallRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->sources())], 'id' => ['required', 'string', 'max:120'], 'versionId' => ['nullable', 'string', 'max:120'], 'loader' => ['nullable', 'string', Rule::in($this->loaders())], 'version' => ['nullable', 'string', 'max:20'], 'title' => ['nullable', 'string', 'max:200'], 'icon' => ['nullable', 'string', 'max:500', 'url'], 'projectUrl' => ['nullable', 'string', 'max:500', 'url'], ]); $loader = (string) ($data['loader'] ?? ''); $loaders = $loader !== '' ? [$loader] : $this->loaders(); try { $resolved = $this->catalogue->download( (string) $data['source'], (string) $data['id'], (string) ($data['versionId'] ?? ''), $loaders, (string) ($data['version'] ?? ''), ); } catch (ConnectionException) { return $this->unreachable(); } if ($resolved === null) { return new JsonResponse([ 'errors' => [['code' => 'NoDownload', 'detail' => 'That has no jar this folder can load: it either publishes no download, or none for ' . implode(', ', $loaders) . '.']], ], 422); } [$url, $filename] = $resolved; $filename = basename($filename); if (!str_ends_with(mb_strtolower($filename), '.jar')) { $filename .= '.jar'; } if (!$this->files($server)->pullFile($this->directory(), $url, $filename)) { return new JsonResponse([ 'errors' => [['code' => 'PullRefused', 'detail' => 'The node could not download that file.']], ], 502); } $this->remember($server, $filename, [ 'source' => (string) $data['source'], 'id' => (string) $data['id'], 'title' => (string) ($data['title'] ?? ''), 'icon' => $this->httpsOnly((string) ($data['icon'] ?? '')), 'url' => $this->httpsOnly((string) ($data['projectUrl'] ?? '')), ]); Activity::event("server:{$this->usageKind()}.install") ->property(['source' => $data['source'], 'file' => $filename]) ->log(); return new JsonResponse(['installed' => true, 'file' => $filename]); } public function toggle(AddonToggleRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:255']]); $from = $this->safeName($data['file']); if ($from === null) { return $this->notAJar(); } $to = str_ends_with($from, self::DISABLED_SUFFIX) ? mb_substr($from, 0, -mb_strlen(self::DISABLED_SUFFIX)) : $from . self::DISABLED_SUFFIX; if (!$this->files($server)->renamePath($this->directory(), $from, $to)) { return new JsonResponse([ 'errors' => [['code' => 'RenameFailed', 'detail' => 'That could not be changed.']], ], 502); } $this->forget($server, $from, $to); Activity::event("server:{$this->usageKind()}.toggle") ->property(['from' => $from, 'to' => $to]) ->log(); return new JsonResponse(['file' => $to]); } public function destroy(AddonDeleteRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:255']]); $file = $this->safeName($data['file']); if ($file === null) { return $this->notAJar(); } if (!$this->files($server)->deletePaths($this->directory(), [$file])) { return new JsonResponse([ 'errors' => [['code' => 'DeleteFailed', 'detail' => 'That could not be removed.']], ], 502); } $this->forget($server, $file); Activity::event("server:{$this->usageKind()}.delete")->property('file', $file)->log(); return new JsonResponse(['deleted' => true]); } protected function manifest(Server $server): array { $raw = \Pterodactyl\Services\Dezerx\Brand::read($this->files($server), $this->directory(), self::MANIFEST_SUFFIX, self::MANIFEST_LIMIT); if ($raw === null || $raw === '') { return []; } $decoded = json_decode($raw, true); return is_array($decoded) ? array_filter($decoded, 'is_array') : []; } protected function putManifest(Server $server, array $manifest): void { $encoded = json_encode($manifest, JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT); if ($encoded !== false && mb_strlen($encoded) <= self::MANIFEST_LIMIT) { \Pterodactyl\Services\Dezerx\Brand::write($this->files($server), $this->directory(), self::MANIFEST_SUFFIX, $encoded); } } protected function remember(Server $server, string $file, array $entry): void { $manifest = $this->manifest($server); $manifest[$file] = array_filter($entry, fn (string $value) => $value !== ''); $this->putManifest($server, $manifest); } protected function forget(Server $server, string $file, ?string $renamedTo = null): void { $manifest = $this->manifest($server); if (!isset($manifest[$file])) { return; } $entry = $manifest[$file]; unset($manifest[$file]); if ($renamedTo !== null) { $manifest[$renamedTo] = $entry; } $this->putManifest($server, $manifest); } protected function httpsOnly(string $url): string { return str_starts_with(mb_strtolower($url), 'https://') ? $url : ''; } protected function installed(Server $server): array { $entries = $this->files($server)->listFiles($this->directory()); if ($entries === null) { return ['available' => false, 'addons' => []]; } $manifest = $this->manifest($server); $addons = []; foreach ($entries as $entry) { $name = (string) ($entry['name'] ?? ''); $lower = mb_strtolower($name); if (($entry['directory'] ?? false) === true) { continue; } if (!str_ends_with($lower, '.jar') && !str_ends_with($lower, '.jar' . self::DISABLED_SUFFIX)) { continue; } $disabled = str_ends_with($lower, self::DISABLED_SUFFIX); $known = $manifest[$name] ?? []; $title = trim((string) ($known['title'] ?? '')); $addons[] = [ 'file' => $name, 'name' => $title !== '' ? $title : $this->readableName($name, $disabled), 'size' => (int) ($entry['size'] ?? 0), 'modifiedAt' => $entry['modified_at'] ?? null, 'disabled' => $disabled, 'icon' => ($known['icon'] ?? '') !== '' ? (string) $known['icon'] : null, 'url' => ($known['url'] ?? '') !== '' ? (string) $known['url'] : null, 'source' => ($known['source'] ?? '') !== '' ? (string) $known['source'] : null, ]; } usort($addons, fn (array $a, array $b) => strcasecmp($a['name'], $b['name'])); return ['available' => true, 'addons' => $addons]; } protected function readableName(string $file, bool $disabled): string { $name = $disabled ? mb_substr($file, 0, -mb_strlen(self::DISABLED_SUFFIX)) : $file; $name = preg_replace('/\.jar$/i', '', $name) ?? $name; return str_replace(['-', '_'], ' ', $name); } protected function safeName(string $file): ?string { $file = trim($file); if ($file === '' || $file !== basename($file) || str_contains($file, '/')) { return null; } $lower = mb_strtolower($file); return str_ends_with($lower, '.jar') || str_ends_with($lower, '.jar' . self::DISABLED_SUFFIX) ? $file : null; } protected function files(Server $server): ServerFiles { return new ServerFiles($server); } private function unreachable(): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'CatalogueUnreachable', 'detail' => 'That catalogue could not be reached. Try again shortly.']], ], 504); } private function notAJar(): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'NotAJar', 'detail' => 'That is not a jar in this folder.']], ], 422); } } 